```json
{
 "didatica": [
  {
   "campo": "resolucao.antes.texto",
   "depois": "Manchetes de jornal usam palavras curtas e fortes. Traduza cada palavra-chave e confira se a alternativa diz o mesmo. Aqui há uma palavra nova (crackdown) e duas que escondem o sentido: mosque e stabbing. A manchete traz duas notícias separadas pelo 'and'.",
   "motivo": "Texto mais direto e já avisa que são duas notícias."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["crackdown", "ação dura das autoridades, medidas severas contra algo"],
    ["stabbing", "facada, ataque com faca"],
    ["mosque", "mesquita, templo muçulmano"],
    ["coal fire", "fogo de carvão, queima de carvão para gerar calor"],
    ["temple", "templo, lugar de culto"],
    ["fuel", "combustível"],
    ["shortage", "falta, escassez"],
    ["fair", "feira (não é 'justo' aqui)"],
    ["church", "igreja"],
    ["headline", "manchete, título de uma notícia"]
   ],
   "motivo": "Incluir church e headline, que aparecem na resolução e nas alternativas; esclarecer fair."
  },
  {
   "campo": "resolucao.pista",
   "depois": "Divida a manchete em duas partes, no 'and'. Traduza o assunto de cada uma e procure a alternativa que traz os dois assuntos.",
   "motivo": "Frase mais simples, sem entregar a resposta."
  },
  {
   "campo": "resolucao.passos[0].conta",
   "depois": "Coal fire crackdown\nLondon mosque stabbing",
   "motivo": "Cabe na tela do celular, uma parte por linha."
  },
  {
   "campo": "resolucao.passos[1].conta",
   "depois": "crackdown = medidas severas",
   "motivo": "Mantido, já curto."
  },
  {
   "campo": "resolucao.passos[1].porque",
   "depois": "Coal fire crackdown é medidas duras contra o fogo de carvão, ou seja, contra queimar carvão. Não fala de falta de carvão nem de explosão.",
   "motivo": "Troca 'repressão' por explicação mais simples."
  },
  {
   "campo": "resolucao.passos[3].conta",
   "depois": "A: medidas severas + facada + templo",
   "motivo": "Mostra as duas partes cobertas e cabe na tela."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "Só a letra A traz as duas notícias: medidas severas contra queima de combustível e ataque com faca num templo. Nas outras, uma das partes está trocada.",
   "motivo": "Mais claro e direto."
  },
  {
   "campo": "resolucao.erradas.D",
   "depois": "Junta tudo numa notícia só: restrições ao carvão 'para aquecer casas e templos muçulmanos'. A manchete traz dois fatos separados, e stabbing (facada) some da alternativa.",
   "motivo": "Diz com clareza o que faltou ao aluno que marcou D."
  },
  {
   "campo": "resolucao.erradas.C",
   "depois": "Shortage (falta) não está na manchete: crackdown é medida dura, não escassez. E 'fair' (feira) não aparece; o local é mosque, mesquita.",
   "motivo": "Frases mais curtas e claras."
  }
 ],
